<?php
if (!defined('ABSPATH')) exit;
function gim_create_provider_application($user_id,$data){ global $wpdb; $existing=gim_provider_profile($user_id); if($existing)return new WP_Error('exists','Provider profile already exists.');
 $public='GTM-P-'.str_pad((string)$user_id,5,'0',STR_PAD_LEFT); $wpdb->insert(gim_table('providers'),['user_id'=>$user_id,'public_id'=>$public,'status'=>'pending','business_name'=>sanitize_text_field($data['business_name']??''),'trade_family'=>sanitize_key($data['trade_family']??''),'services_json'=>gim_json(array_values(array_map('sanitize_key',$data['services']??[]))),'coverage_json'=>gim_json(array_values(array_map('sanitize_text_field',$data['coverage']??[]))),'verification_json'=>gim_json(['insurance'=>false,'identity'=>false,'qualifications'=>[]]),'created_at'=>gim_now(),'updated_at'=>gim_now()]); gim_audit('provider.application_created','provider',$public); return $wpdb->insert_id; }
function gim_provider_bookable($profile,$service_slug){ if(!$profile||$profile->status!=='approved'||!(int)$profile->stripe_ready)return false; $services=gim_decode($profile->services_json); if(!in_array($service_slug,$services,true))return false; $v=gim_decode($profile->verification_json); return !empty($v['identity'])&&!empty($v['insurance']); }
function gim_admin_set_provider_status($provider_id,$status,$verification=[]){ global $wpdb; if(!current_user_can('gim_manage_providers')&&!current_user_can('manage_options'))return new WP_Error('forbidden','Forbidden'); $allowed=['pending','approved','rejected','suspended']; if(!in_array($status,$allowed,true))return new WP_Error('invalid','Invalid status'); $data=['status'=>$status,'updated_at'=>gim_now()]; if($verification)$data['verification_json']=gim_json($verification); $wpdb->update(gim_table('providers'),$data,['id'=>$provider_id]); $p=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('providers').' WHERE id=%d',$provider_id)); if($p&&$status==='approved'){ $u=new WP_User($p->user_id); $u->set_role('gim_provider'); } gim_audit('provider.status_changed','provider',$p?$p->public_id:(string)$provider_id,['status'=>$status]); return true; }
function gim_provider_stripe_onboarding($user_id){ global $wpdb; $p=gim_provider_profile($user_id); if(!$p)return new WP_Error('provider','Provider profile not found.'); $acct=$p->stripe_account_id; if(!$acct){ $u=get_userdata($user_id); $r=gim_stripe_request('POST','accounts',['type'=>'express','country'=>'GB','email'=>$u?$u->user_email:'','capabilities[transfers][requested]'=>'true','metadata[gim_provider_public_id]'=>$p->public_id]); if(is_wp_error($r))return $r; $acct=$r['id']; $wpdb->update(gim_table('providers'),['stripe_account_id'=>$acct,'updated_at'=>gim_now()],['id'=>$p->id]); }
 $return=gim_page_url('gim-provider-dashboard',['stripe'=>'return']); $refresh=gim_page_url('gim-provider-dashboard',['stripe'=>'refresh']); $link=gim_stripe_request('POST','account_links',['account'=>$acct,'refresh_url'=>$refresh,'return_url'=>$return,'type'=>'account_onboarding']); if(is_wp_error($link))return $link; return $link['url']??new WP_Error('stripe','No onboarding URL returned.'); }
function gim_reconcile_stripe_account($account){ global $wpdb; $id=$account['id']??''; if(!$id)return false; $ready=!empty($account['charges_enabled'])&&!empty($account['payouts_enabled'])&&!empty($account['capabilities']['transfers'])&&$account['capabilities']['transfers']==='active'; $wpdb->update(gim_table('providers'),['stripe_ready'=>$ready?1:0,'updated_at'=>gim_now()],['stripe_account_id'=>$id]); return true; }
